package com.meunews.reader

import java.net.URLEncoder

private fun p(n: String, u: String) = Src(n, u, true)
private fun e(n: String, u: String) = Src(n, u, false)
private fun sub(name: String, vararg i: Src) = Sub(name, i.toList())
private fun cat(name: String, vararg s: Sub) = Cat(name, s.toList())
/** "Nome|dominio.com" -> site cujo RSS o app descobre sozinho ao seguir. */
private fun ws(pt: Boolean, vararg x: String) = x.map { val (n, d) = it.split("|"); Src(n, "https://$d#find", pt) }.toTypedArray()
/** Assuntos via Google News: "Nome" ou "Nome|termo de busca". */
private fun gs(vararg q: String) = q.map {
    val (n, k) = if ("|" in it) it.split("|") else listOf(it, it)
    Src(n, "https://news.google.com/rss/search?q=" + URLEncoder.encode(k, "UTF-8") + "&hl=pt-BR&gl=BR&ceid=BR:pt-419", true)
}.toTypedArray()
